## 解题思路

01 串的**评分**定义为：所有只包含字符 `'1'` 的非空连续子串个数。

若某一段连续的 `'1'` 的长度为 $len$，则它贡献的评分为

$$
1+2+\dots+len = \frac{len(len+1)}{2}.
$$

整个序列的评分等于所有连续 `'1'` 段贡献之和。

每次操作只翻转一个位置 $p$，只有包含位置 $p$ 的连续段会发生变化，其他位置贡献不变。因此我们可以动态维护序列的评分：

1. 用有序集合（或树状数组）动态维护所有字符 `'0'` 的位置，并增设**左右哨兵** $0$ 和 $n+1$，保证每个位置都能找到左右最近的 `'0'`。
2. 对于一次翻转操作的位置 $p$：
   - 设 $L$ 为 $p$ 左侧最近的 `'0'` 位置，$R$ 为 $p$ 右侧最近的 `'0'` 位置。
   - 记左侧连续 `'1'` 的长度为 $a = p - L - 1$，右侧连续 `'1'` 的长度为 $b = R - p - 1$。
   - 若 $s[p] = 0$（变为 `'1'`）：  
     相当于把左右两段 `'1'` 与位置 $p$ 合并，新增的评分为 $(a+1)(b+1)$，答案增加该值，并在集合中删去该 `'0'`。
   - 若 $s[p] = 1$（变为 `'0'`）：  
     相当于把一整段 `'1'` 拆成左右两段，减少的评分为 $(a+1)(b+1)$，答案减去该值，并在集合中插入该 `'0'`。
3. 每次操作后输出当前答案。

初始答案可以在读入字符串时扫描所有连续 `'1'` 段并累加计算出。

## 复杂度分析

- 时间复杂度：初始化扫描字符串 $O(n)$，每次操作需要查询和更新有序集合，复杂度 $O(\log n)$；共 $q$ 次操作，总时间复杂度 $O((n+q)\log n)$。
- 空间复杂度：有序集合及辅助数组均占用 $O(n)$ 空间。

## 代码实现

### Python

```python
import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)

    def add(self, i, v):
        # 单点修改：把位置 i 的计数加上 v
        while i <= self.n:
            self.tree[i] += v
            i += i & -i

    def sum(self, i):
        # 查询前缀 [1, i] 中 0 的个数
        res = 0
        while i > 0:
            res += self.tree[i]
            i -= i & -i
        return res

    def kth(self, k):
        # 查询第 k 个 0 在树状数组中的下标
        idx = 0
        bit = 1
        while bit * 2 <= self.n:
            bit *= 2

        while bit > 0:
            nxt = idx + bit
            if nxt <= self.n and self.tree[nxt] < k:
                idx = nxt
                k -= self.tree[nxt]
            bit //= 2

        return idx + 1


def calc(n, s, ops):
    m = n + 2
    bit = BIT(m)

    # 使用 1 下标存储字符串
    arr = [' '] + list(s)

    # 加入左哨兵 0，映射到树状数组下标 1
    bit.add(1, 1)

    # 加入字符串中所有 0 的位置，原位置 pos 映射到 pos + 1
    for i in range(1, n + 1):
        if arr[i] == '0':
            bit.add(i + 1, 1)

    # 加入右哨兵 n + 1，映射到树状数组下标 n + 2
    bit.add(n + 2, 1)

    ans = 0
    cnt = 0

    # 计算初始评分：每段连续 1 的贡献为 len * (len + 1) / 2
    for ch in s:
        if ch == '1':
            cnt += 1
        else:
            ans += cnt * (cnt + 1) // 2
            cnt = 0
    ans += cnt * (cnt + 1) // 2

    res = []

    for p in ops:
        idx = p + 1

        if arr[p] == '0':
            # p 当前是 0，翻转成 1，需要删除这个 0
            left_cnt = bit.sum(idx - 1)
            right_cnt = bit.sum(idx) + 1

            l = bit.kth(left_cnt) - 1
            r = bit.kth(right_cnt) - 1

            a = p - l - 1
            b = r - p - 1

            ans += (a + 1) * (b + 1)

            bit.add(idx, -1)
            arr[p] = '1'
        else:
            # p 当前是 1，翻转成 0，需要加入这个 0
            left_cnt = bit.sum(idx - 1)
            right_cnt = bit.sum(idx) + 1

            l = bit.kth(left_cnt) - 1
            r = bit.kth(right_cnt) - 1

            a = p - l - 1
            b = r - p - 1

            ans -= (a + 1) * (b + 1)

            bit.add(idx, 1)
            arr[p] = '0'

        res.append(ans)

    return res


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    q = int(data[1])
    s = data[2].decode()

    ops = []
    for i in range(q):
        ops.append(int(data[3 + i]))

    res = calc(n, s, ops)

    print('\n'.join(map(str, res)))


if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
import java.util.TreeSet;

public class Main {
    static long[] calc(int n, String s, int[] ops) {
        TreeSet<Integer> zero = new TreeSet<>();
        char[] arr = new char[n + 1];

        // 使用 1 下标存储字符串，方便按题目位置访问
        for (int i = 1; i <= n; i++) {
            arr[i] = s.charAt(i - 1);
        }

        // 加入左右哨兵，保证每个位置都能找到左右最近的 0
        zero.add(0);
        zero.add(n + 1);

        // 记录所有字符 0 的位置
        for (int i = 1; i <= n; i++) {
            if (arr[i] == '0') {
                zero.add(i);
            }
        }

        long ans = 0;
        long cnt = 0;

        // 计算初始评分：每段连续 1 的贡献为 len * (len + 1) / 2
        for (int i = 1; i <= n; i++) {
            if (arr[i] == '1') {
                cnt++;
            } else {
                ans += cnt * (cnt + 1) / 2;
                cnt = 0;
            }
        }
        ans += cnt * (cnt + 1) / 2;

        long[] res = new long[ops.length];

        for (int i = 0; i < ops.length; i++) {
            int p = ops[i];

            if (arr[p] == '0') {
                // p 当前是 0，翻转成 1，会合并左右两段连续 1
                int l = zero.lower(p);
                int r = zero.higher(p);

                long a = p - l - 1L;
                long b = r - p - 1L;

                ans += (a + 1) * (b + 1);

                zero.remove(p);
                arr[p] = '1';
            } else {
                // p 当前是 1，翻转成 0，会把一段连续 1 拆成左右两段
                int l = zero.lower(p);
                int r = zero.higher(p);

                long a = p - l - 1L;
                long b = r - p - 1L;

                ans -= (a + 1) * (b + 1);

                zero.add(p);
                arr[p] = '0';
            }

            res[i] = ans;
        }

        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());

        String s = br.readLine().trim();

        int[] ops = new int[q];
        for (int i = 0; i < q; i++) {
            ops[i] = Integer.parseInt(br.readLine().trim());
        }

        long[] res = calc(n, s, ops);

        StringBuilder sb = new StringBuilder();
        for (long x : res) {
            sb.append(x).append('\n');
        }

        System.out.print(sb.toString());
    }
}
