### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<long long> calc(int n, string s, vector<int>& ops) {
    set<int> zero;
    vector<char> arr(n + 1);

    // 使用 1 下标存储字符串，方便按题目位置访问
    for (int i = 1; i <= n; i++) {
        arr[i] = s[i - 1];
    }

    // 加入左右哨兵，保证每个位置都能找到左右最近的 0
    zero.insert(0);
    zero.insert(n + 1);

    // 记录所有字符 0 的位置
    for (int i = 1; i <= n; i++) {
        if (arr[i] == '0') {
            zero.insert(i);
        }
    }

    long long ans = 0;
    long long cnt = 0;

    // 计算初始评分：每段连续 1 的贡献为 len * (len + 1) / 2
    for (int i = 1; i <= n; i++) {
        if (arr[i] == '1') {
            cnt++;
        } else {
            ans += cnt * (cnt + 1) / 2;
            cnt = 0;
        }
    }
    ans += cnt * (cnt + 1) / 2;

    vector<long long> res;

    for (int p : ops) {
        if (arr[p] == '0') {
            // p 当前是 0，翻转成 1，会合并左右两段连续 1
            auto it = zero.find(p);

            int l = *prev(it);
            int r = *next(it);

            long long a = p - l - 1LL;
            long long b = r - p - 1LL;

            ans += (a + 1) * (b + 1);

            zero.erase(it);
            arr[p] = '1';
        } else {
            // p 当前是 1，翻转成 0，会把一段连续 1 拆成左右两段
            auto it = zero.upper_bound(p);

            int r = *it;
            int l = *prev(it);

            long long a = p - l - 1LL;
            long long b = r - p - 1LL;

            ans -= (a + 1) * (b + 1);

            zero.insert(p);
            arr[p] = '0';
        }

        res.push_back(ans);
    }

    return res;
}

int main() {
