    int n, q;
    cin >> n >> q;

    string s;
    cin >> s;

    vector<int> ops(q);
    for (int i = 0; i < q; i++) {
        cin >> ops[i];
    }

    vector<long long> res = calc(n, s, ops);

    for (long long x : res) {
        cout << x << '\n';
    }

    return 0;
}
